import java.util.LinkedList;
import java.util.Queue;

// One section of the venue: a fixed capacity, how many are sold, and a
// FIFO queue of fans waiting for a spot to open up once the section is full
class Section {
    private String name;           // e.g. "GA" or "VIP"
    private int capacity;          // maximum tickets this section can ever hold
    private int ticketsSold;       // how many have actually been sold so far
    private Queue<String> waitlist; // user ids waiting, in strict arrival order

    Section(String name, int capacity) {
        this.name = name;
        this.capacity = capacity;
        this.ticketsSold = 0;             // nobody has bought a ticket yet
        this.waitlist = new LinkedList<>(); // starts empty
    }

    String getName() {
        return name; // simple accessor
    }

    int getCapacity() {
        return capacity; // simple accessor
    }

    boolean hasSpace() {
        return ticketsSold < capacity; // true only if at least one spot remains
    }

    void sellOneTicket() {
        ticketsSold++; // one more spot is now taken
    }

    void releaseOneTicket() {
        ticketsSold--; // a cancellation frees up exactly one spot
    }

    void addToWaitlist(String userId) {
        waitlist.add(userId); // joins the back of the line
    }

    // Removes and returns the fan who has been waiting the longest, or null if nobody is waiting
    String pollWaitlist() {
        return waitlist.poll(); // LinkedList's poll() removes from the front, FIFO order
    }

    boolean hasWaitlist() {
        return !waitlist.isEmpty(); // true if at least one fan is still waiting
    }
}

