    int capacity;             // maximum tickets this section can ever hold
    int ticketsSold;          // how many have actually been sold so far
    queue<string> waitlist;   // user ids waiting, in strict arrival order

public:
    Section(string name, int capacity) : name(name), capacity(capacity), ticketsSold(0) {}
    // ticketsSold(0): nobody has bought a ticket yet, waitlist starts empty automatically

    string getName() {
        return name; // simple accessor
    }

    int getCapacity() {
        return capacity; // simple accessor
    }

    bool hasSpace() {
        return ticketsSold < capacity; // true only if at least one spot remains
    }

    void sellOneTicket() {
        ticketsSold++; // one more spot is now taken
    }

    void releaseOneTicket() {
        ticketsSold--; // a cancellation frees up exactly one spot
    }

    void addToWaitlist(string userId) {
        waitlist.push(userId); // joins the back of the line
    }

    // Removes and returns the fan who has been waiting the longest, or "" if nobody is waiting
    string pollWaitlist() {
        if (waitlist.empty()) return ""; // nobody is waiting
        string next = waitlist.front();  // front() reads the oldest entry, FIFO order
        waitlist.pop();                  // actually remove it from the queue
        return next;
    }

    bool hasWaitlist() {
        return !waitlist.empty(); // true if at least one fan is still waiting
    }
