import java.util.Map;
import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;

// Observer pattern: anything that wants to react to a ticketing event implements this
interface TicketingObserver {
    void onPurchased(String userId, String sectionName, double price);
    void onWaitlisted(String userId, String sectionName);
    void onPromoted(String userId, String sectionName);
}

// One concrete observer: simply prints every event to the console
class ConsoleTicketingObserver implements TicketingObserver {
    @Override
    public void onPurchased(String userId, String sectionName, double price) {
        // report who bought a ticket, for which section, and at what price
        System.out.println(userId + " purchased a ticket for " + sectionName + " at " + price);
    }

    @Override
    public void onWaitlisted(String userId, String sectionName) {
        // report that a fan joined the waitlist because the section was full
        System.out.println(userId + " joined the waitlist for " + sectionName + " (sold out)");
    }

    @Override
    public void onPromoted(String userId, String sectionName) {
        // report that a waitlisted fan was automatically promoted after a cancellation
        System.out.println(userId + " was promoted from the waitlist for " + sectionName);
    }
}

// Orchestrates purchases, waitlisting, and cancellation-triggered promotion
public class TicketingService {
    private Map<String, Section> sections;              // section name -> that section
    private PricingStrategy pricingStrategy;             // however prices are decided
    private List<TicketingObserver> observers = new ArrayList<>(); // everyone watching for events

    public TicketingService(List<Section> sectionList, PricingStrategy pricingStrategy) {
        this.sections = new HashMap<>();
        for (Section section : sectionList) {
            sections.put(section.getName(), section); // index every section by name
        }
        this.pricingStrategy = pricingStrategy;
    }

    public void addObserver(TicketingObserver observer) {
        observers.add(observer); // register a new observer, does not replace existing ones
    }

    // Attempts to sell one ticket in the named section, or waitlists the fan if it is full.
    // Returns true if a ticket was actually sold, false if the fan was waitlisted instead
    public boolean purchaseTicket(String userId, String sectionName) {
        Section section = sections.get(sectionName);
        if (section == null) {
            return false; // the section does not exist at all, nothing to do
        }

        if (section.hasSpace()) {
            // there is room, sell the ticket immediately
            section.sellOneTicket();
            double price = pricingStrategy.getPrice(section);
            for (TicketingObserver observer : observers) {
                observer.onPurchased(userId, sectionName, price);
            }
            return true;
        } else {
            // no room left, join the waitlist instead of failing outright
            section.addToWaitlist(userId);
            for (TicketingObserver observer : observers) {
                observer.onWaitlisted(userId, sectionName);
            }
            return false;
        }
    }

    // Cancels one ticket in the named section, automatically promoting
    // the longest-waiting fan on that section's waitlist, if anyone is waiting
    public void cancelTicket(String sectionName) {
        Section section = sections.get(sectionName);
        if (section == null) {
            return; // nothing to cancel on a section that does not exist
        }

        section.releaseOneTicket(); // free up the spot this cancellation created

        if (section.hasWaitlist()) {
            // someone was waiting, immediately give them the freed-up spot
            String promotedUserId = section.pollWaitlist();
            section.sellOneTicket(); // the promoted fan now occupies that spot
            for (TicketingObserver observer : observers) {
                observer.onPromoted(promotedUserId, sectionName);
            }
        }
        // if nobody was waiting, the spot simply stays open for the next new request
    }
}

