    void onPurchased(string userId, string sectionName, double price) override {
        cout << userId << " purchased a ticket for " << sectionName << " at " << price << endl;
    }

    void onWaitlisted(string userId, string sectionName) override {
        cout << userId << " joined the waitlist for " << sectionName << " (sold out)" << endl;
    }

    void onPromoted(string userId, string sectionName) override {
        cout << userId << " was promoted from the waitlist for " << sectionName << endl;
    }
};

class TicketingService {
private:
    unordered_map<string, Section> sections;
    PricingStrategy* pricingStrategy;
    vector<TicketingObserver*> observers;

public:
    TicketingService(vector<Section> sectionList, PricingStrategy* pricingStrategy)
        : pricingStrategy(pricingStrategy) {
        for (auto& section : sectionList) {
            sections.insert({section.getName(), section});
        }
    }

    void addObserver(TicketingObserver* observer) {
        observers.push_back(observer);
    }

    bool purchaseTicket(string userId, string sectionName) {
        auto it = sections.find(sectionName);
        if (it == sections.end()) return false;
        Section& section = it->second;

        if (section.hasSpace()) {
            section.sellOneTicket();
            double price = pricingStrategy->getPrice(section);
            for (auto listener : observers) {
                listener->onPurchased(userId, sectionName, price);
            }
            return true;
        } else {
            section.addToWaitlist(userId);
            for (auto listener : observers) {
                listener->onWaitlisted(userId, sectionName);
            }
            return false;
        }
    }

    void cancelTicket(string sectionName) {
        auto it = sections.find(sectionName);
        if (it == sections.end()) return;
        Section& section = it->second;

        section.releaseOneTicket();

        if (section.hasWaitlist()) {
            string promotedUserId = section.pollWaitlist();
            section.sellOneTicket();
            for (auto listener : observers) {
                listener->onPromoted(promotedUserId, sectionName);
            }
        }
    }
};

int main() {
    // A tiny GA section with capacity for only 2 fans, to demonstrate sellout and waitlisting
    vector<Section> sectionList = {Section("GA", 2)};

    TieredPricingStrategy pricing;
    TicketingService service(sectionList, &pricing);
    ConsoleTicketingObserver observer;
    service.addObserver(&observer); // print every event

    service.purchaseTicket("Alice", "GA"); // succeeds, 1 of 2 spots taken
    service.purchaseTicket("Bob", "GA");   // succeeds, 2 of 2 spots taken, now full
    service.purchaseTicket("Carol", "GA"); // section full, Carol joins the waitlist

    service.cancelTicket("GA"); // Bob or Alice cancels, Carol is automatically promoted

    return 0;
}
